-- Generated by `npm run cards:ingest` from the Abilities sheet. Safe to re-run: it replaces every card.
create table if not exists cards (
  id                 text primary key,
  source_type        text not null check (source_type in ('tradition', 'path', 'career')),
  source_name        text not null,
  path               text not null default '',
  archetype          text not null default '',
  tier               int  not null check (tier between 0 and 3),
  name               text not null,
  content            text not null,
  prerequisite_text  text not null default '',
  prerequisite       jsonb,
  action_roll        text not null default 'No',
  willpower_cost     int,
  willpower_cost_note text not null default '',
  rules_version      text not null,
  sort               int  not null default 0
);
alter table cards enable row level security;

insert into cards (id, source_type, source_name, path, archetype, tier, name, content, prerequisite_text, prerequisite, action_roll, willpower_cost, willpower_cost_note, rules_version, sort) values
  ('force-casting.none.basic-force-powers', 'tradition', 'Force casting', '', '', 0, 'Basic Force powers', 'Telekinesis: You are able to lift, move or manipulate objects you could lift without the Force. You may attempt to move Adversaries by making a Force casting roll against them. If the Adversary is smaller than you, roll with Advantage; if they are larger, roll with Disadvantage.
Life force transfer: Make a Force casting roll against an organic Adversary you can touch. On a success, you drain 1 HP from the target to replenish your own HP by 1. Alternatively, no roll required, you may transfer any number of HP from yourself to another organic Hero or NPC.
Evade: As a Trigger move in response to an incoming attack, add +3 to your Evasion to dodge the attack.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 1, '1 (Evade Trigger)', '1.2.0', 1),
  ('force-casting.none.force-movement', 'tradition', 'Force casting', '', '', 0, 'Force movement', 'The Force carries your body across the battlefield. You gain the following:
Dash: Mark off 1 WP to move twice your speed in a straight line without making an Athletics (STR) roll, ignoring difficult terrain.
Leap: As part of a move, mark off 1 WP to spring up to Standard range in any direction, including straight up. You take no falling damage if you land within this distance.
Control descent: As a Trigger move in response to falling, slow your descent, taking no damage and landing on your feet.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'No', 1, '1 per use', '1.2.0', 2),
  ('force-casting.none.force-senses', 'tradition', 'Force casting', '', '', 0, 'Force senses', 'You reach out with your feelings and the Force answers. You gain the following:
Sense danger: You have Advantage on rolls to avoid being surprised, and cannot be attacked by Hidden Adversaries with Advantage.
Sense emotions: Make a Force casting roll against a target you can see. On a success, you read their surface emotions and sense whether they intend you harm.
Psychometry: By touching an object, mark off 1 WP to glimpse a significant moment from its past, at the GM''s discretion.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 1, '1 (Psychometry)', '1.2.0', 3),
  ('force-casting.none.force-finesse', 'tradition', 'Force casting', '', '', 0, 'Force finesse', 'You bend the Force to nudge, shove and disarm. You gain the following:
Push or pull: Make a Force casting roll against a target in Standard range. On a success, move them up to Near range towards or away from you.
Disarm: Make a Force casting roll against a target in Standard range. On a success, an object they are holding is pulled from their grasp to a point you can see.
Steady hand: As a Trigger move, hold a loose object, door or lever in place until your next action roll.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 1, '1 (Steady hand Trigger)', '1.2.0', 4),
  ('magick-casting.none.basic-magick-powers', 'tradition', 'Magick casting', '', '', 0, 'Basic Magick powers', 'Telekinesis: You are able to lift, move or manipulate objects you could lift without Magick. You may attempt to move Adversaries by making a Magick casting roll against them.
Spell of cinder: You are able to produce a flame, in the colour of your ichor, and project it into an object, lifeform or droid within range. Flammable objects combust.
Ichor-guided strikes: Ichor steadies your hand. You may use your Magick casting modifier in place of your usual attack modifier for weapon attack rolls.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 5),
  ('magick-casting.none.wardcraft', 'tradition', 'Magick casting', '', '', 0, 'Wardcraft', 'You weave protective spells and cast your senses wide. You gain the following:
Spell of awareness: For a short time, mark off 1 WP to extend your senses so that you cannot be surprised.
Seeking spell: Make a Magick casting roll to sense a specific lifeform or droid you have met, even if Hidden, learning their rough direction and physical state.
Ground restraints: Make a Magick casting roll against a target in Standard range. On a success, mark off 1 additional WP and coils of ichor rise from the ground, leaving them Immobilised until your next action roll.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 (Spell of awareness); 1 on success (Ground restraints)', '1.2.0', 6),
  ('magick-casting.none.enthrall', 'tradition', 'Magick casting', '', '', 0, 'Enthrall', 'Your ichor slips into the minds of the weak-willed. You gain the following:
Mesmerism: Make a Magick casting roll against a lifeform in Standard range. On a success, mark off 1 additional WP and their eyes glow with your ichor; they are Influenced until your next action roll.
Mindspeech: Mark off 1 WP to project your voice and image into the mind of a lifeform you can see, holding a silent conversation.
Spell of comfort: Touch a Dying creature. For a short time they may move and act without marking WP, though they still fall if they take Major damage.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 on success (Mesmerism); 1 (Mindspeech)', '1.2.0', 7),
  ('magick-casting.none.ichorcraft', 'tradition', 'Magick casting', '', '', 0, 'Ichorcraft', 'You shape raw ichor into flame and force. You gain the following:
Ichor blast: Make a Magick casting roll against a target in Far range. On a hit, they take 1d6 ICH damage and any unattended flammable objects nearby catch light.
Enchant weapon: Mark off 1 WP to let ichor course through a weapon you''re holding. For a Countdown (4), its hits deal an additional 1d6 Ichor (ICH) damage.
Cinderbrand: Make a Magick casting roll against a target in Standard range. On a success, ichor-flame clings to them, burning the colour of your ichor; they gain the Burning condition (1d4 FIR on a Countdown (4)).', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 (Enchant weapon)', '1.2.0', 8),
  ('tech-casting.none.basic-tech-powers', 'tradition', 'Tech casting', '', '', 0, 'Basic Tech powers', 'Alarm: Set an alarm for a door, window or area. For one day, you will be alerted if the alarm is triggered.
Lesser hologram: You may project small holographic items for communication purposes, displaying maps or reading data.
Light: You are able to emit light from your tech pad that illuminates a 3m radius sphere.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 9),
  ('tech-casting.none.field-kit', 'tradition', 'Tech casting', '', '', 0, 'Field kit', 'Your tech pad keeps the crew connected and moving. You gain the following:
Communicator: Using the built-in comm-link on your tech pad, you may speak with anyone in range.
Mobile lights: Three small lights rise from your tech pad and follow your commands, illuminating wherever you direct them.
Lock: Mark off 1 WP to seal a door, window, crate or gate in range for a short time, holding it shut against normal means.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'No', 1, '1 (Lock)', '1.2.0', 10),
  ('tech-casting.none.slicers-touch', 'tradition', 'Tech casting', '', '', 0, 'Slicer''s touch', 'You bend machines and droids to your will. You gain the following:
Data spike: Make a Tech casting roll to plug into and hijack a computer system, accessing surveillance or overriding basic security.
Hack droid: Make a Tech casting roll against a droid in range, which may resist. On a success, you access its memory and give it simple instructions.
Repair droid: Touch a droid in range and mark off 1 WP to restore 1d4 HP.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 1, '1 (Repair droid)', '1.2.0', 11),
  ('tech-casting.none.recon-suite', 'tradition', 'Tech casting', '', '', 0, 'Recon suite', 'Your tech pad reads the world so you don''t have to guess. You gain the following:
Scan area: Sweep the area for something specific or to determine details, gaining +5 to Intelligence (Investigation) rolls to do so.
Analyse: Examine a sample of organic material to learn about its properties, history or usage.
Translate language: Using your tech pad, translate any commonly known language into one you understand.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 12),
  ('tech-casting.none.offensive-technology', 'tradition', 'Tech casting', '', '', 1, 'Offensive technology', 'Your tech pad isn''t just a tool, it''s a weapon rack designed to fry as much as it fights. Make a Tech casting roll to do any of the following:
Overcurrent: Make a Tech casting roll against a single Adversary in Standard range. On a success, they take 1d6 Ion (ION) damage. If the target is a droid, they''re also Ionised.
Shrapnel charge: Target all Adversaries in Near range. On a success, those affected take 1d6 Physical (PHY) damage and are knocked back 1.5m.
Additionally, as a Trigger move:
Overload vent: When you take damage, vent excess heat through your pad''s cooling array. If the attacker is within Close range, they take 1d4 Fire (FIR) damage.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 1, '1 (Overload vent Trigger)', '1.2.0', 13),
  ('tech-casting.none.translocate', 'tradition', 'Tech casting', '', '', 1, 'Translocate', 'Your form flickers into a holographic lattice and collapses, reassembling somewhere else. As a manoeuvre, mark off 1 WP to teleport to a space you can see within Standard range. You ignore any gaps or barriers in between, and this movement can''t provoke Trigger moves.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'No', 1, '1', '1.2.0', 14),
  ('bounty-hunter.none.snare-traps', 'career', 'Bounty Hunter', 'Bounty Hunter', '', 1, 'Snare traps', 'Make a Tech casting roll against a target to ensnare them in energy snare traps. On a success, mark off 1 additional WP and your target is Immobilised.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 15),
  ('devout.none.deft-movement', 'path', 'Devout', 'Devout', '', 0, 'Deft movement', 'Once per Short Rest, you may move to anywhere in Far range without making an Athletics (STR) roll. If you end the movement in Close range of a target, you may make an attack roll without marking WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 16),
  ('devout.none.precise-movements', 'path', 'Devout', 'Devout', '', 0, 'Precise movements', 'Your devotion to this Path affords you precise movements. You gain the following:
you ignore difficult terrain constraints
you may break free from the Immobilised condition without marking WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 17),
  ('devout.none.inner-peace', 'path', 'Devout', 'Devout', '', 1, 'Inner peace', 'In a quiet moment between the chaos, you centre yourself in the Force. Once per Full Rest, when you share words of wisdom or encouragement with a Hero, you both clear 2 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 18),
  ('devout.none.one-with-the-force', 'path', 'Devout', 'Devout', '', 1, 'One with the Force', 'And the Force is with you. You gain the following benefits:
once per Full Rest, clear WP equal to your Force (FOR) Trait modifier
once per Full Rest, swap the polarity of a Dyad Dice roll.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 19),
  ('devout.none.untouchable', 'path', 'Devout', 'Devout', '', 1, 'Untouchable', 'Your faith turns blows aside. Add your Force (FOR) Trait modifier to your Evasion.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 20),
  ('devout.none.aura-of-conviction', 'path', 'Devout', 'Devout', '', 2, 'Aura of conviction', 'Your belief radiates outward. Allies in Close range (3m) add +1 to their Evasion while you are conscious.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 21),
  ('devout.none.guided-strike', 'path', 'Devout', 'Devout', '', 2, 'Guided strike', 'The Force moves through your weapon arm. Once per Short Rest, when you miss an attack roll, you may reroll it and take the higher result.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 22),
  ('devout.none.force-conduit', 'path', 'Devout', 'Devout', '', 3, 'Force conduit', 'When you roll your Devout Die for any feature or ability, you may reroll any 1s and 2s, taking the higher result.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 23),
  ('devout.none.transcendent-will', 'path', 'Devout', 'Devout', '', 3, 'Transcendent will', 'Once per Full Rest, when you would be reduced to 0 WP, you instead remain at 1 WP.
Additionally, you may clear one condition affecting you.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 24),
  ('devout.guardian.enlightened', 'path', 'Devout', 'Devout', 'Guardian', 1, 'Enlightened', 'You tap into your faith, granting you the following abilities:
you may make an extra unarmed attack each time you succeed on an attack roll with Balance
mark off 1 WP to add your Force (FOR) Trait modifier to any action roll
mark off 1 WP to add your Force (FOR) Trait modifier to your Evasion until you next take the Focus.', '', 'null'::jsonb, 'Yes', 1, '1 per use (FOR to a roll or Evasion)', '1.2.0', 25),
  ('devout.guardian.trust-fall', 'path', 'Devout', 'Devout', 'Guardian', 1, 'Trust fall', 'As a Trigger move in response to taking damage from falling, roll your Devout Die. Reduce the damage by the amount rolled.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 26),
  ('devout.guardian.with-me', 'path', 'Devout', 'Devout', 'Guardian', 1, 'With me', 'Clear 3 WP of a Hero you can touch. You may use this feature a number of times equal to your Force (FOR) Trait modifier per Full Rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 27),
  ('devout.guardian.shon-ju-scrolls', 'path', 'Devout', 'Devout', 'Guardian', 2, 'Shon-Ju scrolls', 'Brittle scrolls of Shon-Ju katas, each stroke a lesson in stopping a fight without ending a life. You gain the following:
Disarming palm: when you hit with an unarmed attack, you may disarm the target instead of dealing damage.
Shelter: as a Trigger move in response to an ally within Close range being attacked, they gain +2 Evasion against that attack.
Still waters: you have Advantage on Negotiation rolls to de-escalate a violent confrontation.', 'Shon-Ju', '{"kind":"archetype_feature","name":"Shon-Ju","featureKey":"devout/guardian:shon-ju"}'::jsonb, 'No', 1, '1 (Shelter Trigger)', '1.2.0', 28),
  ('devout.guardian.flowing-throw', 'path', 'Devout', 'Devout', 'Guardian', 2, 'Flowing throw', 'Shon-Ju teaches you to turn an attacker''s strength against them. As a Trigger move in response to an Adversary missing you with a melee attack, throw it to a space within Close range of you, knocking it Prone. If you throw it into another Adversary, both take damage equal to your Devout Die.', 'Shon-Ju', '{"kind":"archetype_feature","name":"Shon-Ju","featureKey":"devout/guardian:shon-ju"}'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 29),
  ('marauder.none.not-good-enough', 'path', 'Marauder', 'Marauder', '', 0, 'Not good enough', 'When you roll your damage dice, you can reroll any 1s or 2s.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 30),
  ('marauder.none.reckless', 'path', 'Marauder', 'Marauder', '', 0, 'Reckless', 'Mark off 1 WP to gain Advantage on an attack.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 31),
  ('marauder.none.danger-sense', 'path', 'Marauder', 'Marauder', '', 1, 'Danger sense', 'Your instincts sharpen, letting you sense threats before they strike. Advantage on Agility saving rolls, unless you are Unconscious or Dying.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 32),
  ('marauder.none.love-of-war', 'path', 'Marauder', 'Marauder', '', 1, 'Love of war', 'Clear WP equal to your Strength (STR) Trait modifier. You may use this feature once per Short Rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 33),
  ('marauder.none.momentus-attack', 'path', 'Marauder', 'Marauder', '', 1, 'Momentus attack', 'You swing with everything you''ve got. You may use a melee attack roll on two targets in range, rolling the damage separately.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 34),
  ('marauder.none.adrenaline-surge', 'path', 'Marauder', 'Marauder', '', 2, 'Adrenaline surge', 'Mark off 1 WP when you enter Fury. For the duration, your speed increases by 3m and you ignore difficult terrain.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 35),
  ('marauder.none.brutal-critical', 'path', 'Marauder', 'Marauder', '', 2, 'Brutal critical', 'When you score a Minor Critical hit with an attack roll, roll all damage twice.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 36),
  ('marauder.none.battle-hardened', 'path', 'Marauder', 'Marauder', '', 2, 'Battle-hardened', 'Pain barely registers once you''re in the thick of it. While in Fury, your Major threshold increases by 2.', 'Fury', '{"kind":"path_feature","name":"Fury"}'::jsonb, 'No', 0, 'None', '1.2.0', 37),
  ('marauder.none.unstoppable', 'path', 'Marauder', 'Marauder', '', 3, 'Unstoppable', 'While in Fury, you attempt to move through Adversaries, ignoring size restrictions. Make an Athletics roll against the Adversary''s Difficulty.
If you''ve moved prior, you have Advantage on the roll. On a success, you may push the Adversary 1.5m and you do not trigger opportunity attacks.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 38),
  ('marauder.none.warriors-bond', 'path', 'Marauder', 'Marauder', '', 3, 'Warrior''s bond', 'Once per Full Rest, when you compliment someone or ask them about something they''re good at, you can both clear 3 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 39),
  ('marauder.berserker.blood-in-the-water', 'path', 'Marauder', 'Marauder', 'Berserker', 1, 'Blood in the water', 'The first kill only sharpens the hunger. While in Fury, when you reduce an Adversary to 0 HP, clear 1 WP. You may use this feature a number of times per Full Rest equal to your Strength (STR) modifier (minimum once).', 'Fury', '{"kind":"path_feature","name":"Fury"}'::jsonb, 'No', null, 'None (clears 1)', '1.2.0', 40),
  ('marauder.berserker.seeing-red', 'path', 'Marauder', 'Marauder', 'Berserker', 1, 'Seeing red', 'Pain only feeds you. As a Trigger move in response to taking Major damage or worse while in Fury, add your Fury damage twice to your next melee damage roll.', 'Fury', '{"kind":"path_feature","name":"Fury"}'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 41),
  ('marauder.berserker.war-cry', 'path', 'Marauder', 'Marauder', 'Berserker', 1, 'War cry', 'You announce yourself the way a storm does. When you enter Fury, make one Strength (Coercion) roll and compare it to the Difficulty of each Adversary within Near range who can hear you. On a success, they are Frightened of you until your Fury ends.', 'Fury', '{"kind":"path_feature","name":"Fury"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 42),
  ('marauder.berserker.no-quarter', 'path', 'Marauder', 'Marauder', 'Berserker', 2, 'No quarter', 'Nothing stops you once the blood is up. While in Fury, when you fail a melee attack roll, mark off 1 WP to keep the Focus instead of passing it to the GM. The failure still stands. You may do this once each time you enter Fury.', 'Fury', '{"kind":"path_feature","name":"Fury"}'::jsonb, 'No', 1, '1', '1.2.0', 43),
  ('marauder.berserker.crushing-blow', 'path', 'Marauder', 'Marauder', 'Berserker', 2, 'Crushing blow', 'While in Fury, when you hit with a melee attack, mark off 1 WP to drive the target back. It is knocked Prone and pushed up to 3 m away from you. If it strikes a wall, an obstacle or another creature, it takes your Fury damage again.', 'Fury', '{"kind":"path_feature","name":"Fury"}'::jsonb, 'No', 1, '1', '1.2.0', 44),
  ('marauder.tank.get-back-up', 'path', 'Marauder', 'Marauder', 'Tank', 1, 'Get back up', 'When you are reduced to 0 HP, you can immediately get back up with 1 HP. You may use this feature once per Full Rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 45),
  ('marauder.tank.mental-toughness', 'path', 'Marauder', 'Marauder', 'Tank', 1, 'Mental toughness', 'As a Trigger move in response to being hit, you may reduce incoming damage by one threshold.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 46),
  ('marauder.tank.unarmoured-defence', 'path', 'Marauder', 'Marauder', 'Tank', 1, 'Unarmoured Defence', 'While not wearing Armour, you gain a number of Armour Slots equal to your Agility (AGI) + Resilience (RES) Trait modifiers.
This Armour can be restored using the Tend to Wounds downtime move.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 47),
  ('marauder.tank.come-and-get-me', 'path', 'Marauder', 'Marauder', 'Tank', 2, 'Come and get me', 'You make yourself the biggest problem in the room. As a manoeuvre, mark off 1 WP. Until you next take the Focus, Adversaries within Near range who can see or hear you have Disadvantage on attacks against anyone but you.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 48),
  ('marauder.tank.take-the-hit', 'path', 'Marauder', 'Marauder', 'Tank', 2, 'Take the hit', 'As a Trigger move in response to an ally within Close range taking damage, take it in their place. Your thresholds, armour and resistances apply instead of theirs.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 49),
  ('marauder.tank.fortress', 'path', 'Marauder', 'Marauder', 'Tank', 3, 'Fortress', 'As a Trigger move in response to incoming damage, mark off 1 additional WP and you become resistant to all damage types.', '', 'null'::jsonb, 'No', 2, '2 (Trigger + 1 additional)', '1.2.0', 50),
  ('mystic.none.foreseen-evade', 'path', 'Mystic', 'Mystic', '', 0, 'Foreseen evade', 'As a Trigger move in response to an incoming attack, add +3 to your Evasion. If the attack misses, the attacker has Disadvantage on their next attack against you.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 51),
  ('mystic.none.sense-emotions', 'path', 'Mystic', 'Mystic', '', 0, 'Sense emotions', 'You feel the currents beneath the surface. Make a Force casting roll against a target you can see. On a success, you read their surface emotions and sense whether they intend you harm.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 52),
  ('mystic.none.foresight', 'path', 'Mystic', 'Mystic', '', 1, 'Foresight', 'You see things before they happen. Mark off 1 WP and until you relinquish the Focus you have Advantage on all action rolls.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 53),
  ('mystic.none.improved-life-force-transfer', 'path', 'Mystic', 'Mystic', '', 1, 'Improved life force transfer', 'Make a Force casting roll against an organic Adversary you can touch. On a success, mark off 1 additional WP, and you drain 2 HP from the target to replenish your own HP by 2.
Alternatively, no roll required, you may transfer any number of HP from yourself to another organic Hero or NPC.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 54),
  ('mystic.none.threads-of-calm', 'path', 'Mystic', 'Mystic', '', 1, 'Threads of calm', 'You reach out through the Force, steadying the minds of those around you. Once per Short Rest, choose a Hero in Standard range. You each clear 1 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 55),
  ('mystic.none.force-barrier', 'path', 'Mystic', 'Mystic', '', 2, 'Force barrier', 'As a Trigger move in response to an incoming attack against you or an ally in Close range (3m), project a barrier of Force energy. Reduce the incoming damage by your Mystic Die.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 56),
  ('mystic.none.force-storm', 'path', 'Mystic', 'Mystic', '', 2, 'Force storm', 'You unleash a surge of raw Force energy. Make a Force casting roll against all Adversaries in a Near range (3m) radius.
On a hit, deal 2d6 Energy (NRG) damage and push each target back 1.5m.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 57),
  ('mystic.none.mind-touch', 'path', 'Mystic', 'Mystic', '', 2, 'Mind touch', 'Make a Force casting roll against an organic target in Standard range. On a success, mark off 1 additional WP and choose one:
cloud their mind (they have Disadvantage on their next roll)
probe their thoughts (ask the GM one simple question about the target''s intentions).', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 58),
  ('mystic.none.sever-force', 'path', 'Mystic', 'Mystic', '', 3, 'Sever Force', 'During a Full Rest, spend two downtime moves to enter deep meditation and cut yourself off from the Force. Until reversed, you are imperceptible to the Force and cannot be sensed by Force users.
You also lose access to all Force powers and abilities. You remain severed until you use this ability again to reconnect with the Force, as a single downtime move on a Full Rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 59),
  ('mystic.none.unbreakable-sight', 'path', 'Mystic', 'Mystic', '', 3, 'Unbreakable sight', 'You see beyond the veil. You gain Advantage on all saving rolls against being Frightened, Influenced, or Stunned. Additionally, attacks from unseen Adversaries no longer have Advantage against you.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 60),
  ('mystic.none.attuned', 'path', 'Mystic', 'Mystic', '', 3, 'Attuned', 'The Force answers you before you finish asking. Add +1 to your Force casting rolls.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'No', 0, 'None', '1.2.0', 61),
  ('mystic.cosmic.battle-meditation', 'path', 'Mystic', 'Mystic', 'Cosmic', 1, 'Battle meditation', 'Mark off 1 WP to emit an aura that affects Heroes and Adversaries in Standard range.
Heroes gain Advantage on all action rolls, and Adversaries have Disadvantage on all action and attack rolls.
The aura lasts until you end it or fall Unconscious. Each time you are hit by an attack, mark off 1 WP to maintain it; if you cannot or will not, it ends.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 62),
  ('mystic.cosmic.cognitive-teachings', 'path', 'Mystic', 'Mystic', 'Cosmic', 1, 'Cognitive teachings', 'You understand that the Force can be used to influence others:
Mind trick: Make a Force casting roll and utter a phrase or gesture to alter the mind or opinion of one organic in Near range.
Cloud mind: Make a Force casting roll to confuse an organic in Near range.
Mind probe: Make a Force casting roll to uncover simple secrets, information or memory from an organic in Near range.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 63),
  ('mystic.cosmic.flow-step', 'path', 'Mystic', 'Mystic', 'Cosmic', 1, 'Flow step', 'You move as the Force moves. Move to anywhere within Far range, in any path, without making an Athletics (STR) roll. Adversaries'' Trigger moves can''t be triggered by this movement. You may do this a number of times per Short Rest equal to your Force (FOR) Trait modifier (minimum once).', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 64),
  ('mystic.cosmic.holocron-of-the-living-force', 'path', 'Mystic', 'Mystic', 'Cosmic', 2, 'Holocron of the Living Force', 'A crystal holocron that hums in time with every living thing around it. You gain the following:
Glimpse: once per Full Rest, ask the GM one yes-or-no question about the near future, which they must answer honestly.
Nudge fate: as a Trigger move in response to an ally within Near range making a saving roll, add your Mystic Die to it.
Attunement: you sense the number and rough nature of living things within Standard range, even through walls.', '', 'null'::jsonb, 'No', 1, '1 (Nudge fate Trigger)', '1.2.0', 65),
  ('mystic.cosmic.bend-the-current', 'path', 'Mystic', 'Mystic', 'Cosmic', 2, 'Bend the current', 'You tug on the threads of fate around an enemy''s aim. As a Trigger move in response to an Adversary within Far range making an attack roll, roll your Mystic Die and subtract the result from its attack roll before the GM determines hit or miss.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 66),
  ('sentinel.none.improved-evade', 'path', 'Sentinel', 'Sentinel', '', 0, 'Improved evade', 'As a Trigger move in response to an incoming attack, mark off 1 additional WP to add +5 to your Evasion to dodge the attack.', 'Evade', '{"kind":"card","name":"Basic Force powers","cardId":"force-casting.none.basic-force-powers"}'::jsonb, 'No', 2, '2 (Trigger + 1 additional)', '1.2.0', 67),
  ('sentinel.none.sense-danger', 'path', 'Sentinel', 'Sentinel', '', 0, 'Sense danger', 'The Force warns you before the blow lands. You have Advantage on rolls to avoid being surprised, and Hidden Adversaries cannot attack you with Advantage.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 68),
  ('sentinel.none.momentus-attack', 'path', 'Sentinel', 'Sentinel', '', 1, 'Momentus attack', 'The Force carries your strike through more than one foe. You may use a melee attack roll on two targets in range, rolling the damage separately.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 69),
  ('sentinel.none.resolute-focus', 'path', 'Sentinel', 'Sentinel', '', 1, 'Resolute focus', 'Your discipline is unshakeable. Once per Short Rest, when you take the Focus, you may clear 2 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 70),
  ('force-casting.none.trained-in-the-arts', 'tradition', 'Force casting', '', '', 1, 'Trained in the Arts', 'You are more adept with the Force than someone untrained:
Stasis: As a Trigger move in response to an object or projectile in motion, freeze it in space until your next action roll.
Repulse: Make a Force casting roll against any target in Close range. On a success against one or more targets, mark off 1 additional WP and push all affected targets back 3m. Pushed targets take 2d6 PHY damage.
Deflection: As a Trigger move, you may redirect any projectile to miss a target it would have ordinarily hit. If you wish to aim the projectile at another target instead, make a casting roll to do so.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 1, '1 (Stasis and Deflection Triggers); 1 on success (Repulse)', '1.2.0', 71),
  ('sentinel.none.force-slam', 'path', 'Sentinel', 'Sentinel', '', 2, 'Force slam', 'You unleash a concussive shockwave in the Force:
make a Force casting roll against all Adversaries in Near range (3m)
each affected Adversary is knocked Prone and takes 2d6 Physical (PHY) damage.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 72),
  ('sentinel.none.forceful-advance', 'path', 'Sentinel', 'Sentinel', '', 2, 'Forceful advance', 'When you move at least 3m before attacking, your first melee attack deals +2 damage and you gain +2 Evasion until you relinquish the Focus.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 73),
  ('sentinel.none.battle-harmony', 'path', 'Sentinel', 'Sentinel', '', 3, 'Battle harmony', 'When you take the Focus, choose a combat stance:
Aggressive: +2 to attack rolls
Defensive: +2 to Evasion. Switching stances mid-Focus costs 1 WP.
Your stance ends when you next seize the Focus.', '', 'null'::jsonb, 'No', 1, '1 to switch stance', '1.2.0', 74),
  ('sentinel.none.calm-in-the-storm', 'path', 'Sentinel', 'Sentinel', '', 3, 'Calm in the storm', 'The harder the fight, the quieter your mind. When you succeed with Balance on a Force casting roll, clear 1 additional WP.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'No', null, 'None (clears 1)', '1.2.0', 75),
  ('sentinel.blademaster.empowered-attack', 'path', 'Sentinel', 'Sentinel', 'Blademaster', 1, 'Empowered attack', 'When you hit with a melee weapon attack, you may mark off 1 WP to add your Sentinel Die to the damage roll.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 76),
  ('sentinel.blademaster.saber-throw', 'path', 'Sentinel', 'Sentinel', 'Blademaster', 1, 'Saber throw', 'Make a Force casting roll against an Adversary''s Difficulty. On a hit, you propel your lightsaber or melee weapon at the target at Standard range. Deal the weapon''s normal damage.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 77),
  ('sentinel.blademaster.sun-djem', 'path', 'Sentinel', 'Sentinel', 'Blademaster', 1, 'Sun djem', 'Make an attack roll with your lightsaber. On a hit, you can make an action roll to disarm the target of any weapons.
On a success, the target is disarmed without any physical harm.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 78),
  ('sentinel.blademaster.holocron-of-the-forms', 'path', 'Sentinel', 'Sentinel', 'Blademaster', 2, 'Holocron of the Forms', 'A training holocron, its gatekeeper a duellist long since one with the Force. You gain the following:
Soresu guard: when you Block, you also gain +1 Evasion against energy attacks until you next take the Focus.
Ataru leap: as part of a melee attack, you may move up to Near range, including onto higher ground, without making an Athletics (STR) roll.
Read the form: you have Advantage on Insight rolls to read another duellist''s training, style and lineage.', 'Duelist', '{"kind":"archetype_feature","name":"Duelist","featureKey":"sentinel/blademaster:duelist"}'::jsonb, 'No', 0, 'None', '1.2.0', 79),
  ('sentinel.blademaster.shien-deflection', 'path', 'Sentinel', 'Sentinel', 'Blademaster', 2, 'Shien deflection', 'As a Trigger move, when you Block a ranged energy attack and it misses, mark off 1 additional WP to send the bolt back. Make a Force casting roll against the attacker''s Difficulty. On a success, it takes the attack''s damage.', 'Duelist', '{"kind":"archetype_feature","name":"Duelist","featureKey":"sentinel/blademaster:duelist"}'::jsonb, 'Yes', 2, '2 (Trigger + 1 additional), on top of Block', '1.2.0', 80),
  ('sentinel.striker.momentus-strike', 'path', 'Sentinel', 'Sentinel', 'Striker', 0, 'Momentus strike', 'When you move as part of your attack roll, you may add your Sentinel Die to the damage roll.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 81),
  ('sentinel.striker.crippling-blow', 'path', 'Sentinel', 'Sentinel', 'Striker', 1, 'Crippling blow', 'When you hit with a melee attack, you may mark off 1 WP to add your Sentinel Die to the damage roll.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 82),
  ('sentinel.striker.guided-combat', 'path', 'Sentinel', 'Sentinel', 'Striker', 1, 'Guided combat', 'You know the following Trigger moves in response to oncoming attacks that deal PHY damage:
Block: add your FOR Trait modifier to your Evasion before the GM determines a hit or miss
Deflect: reduce the damage by rolling your Sentinel Die.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 83),
  ('sentinel.striker.successive-strikes', 'path', 'Sentinel', 'Sentinel', 'Striker', 1, 'Successive strikes', 'When you hit with a melee attack, you may mark off 1 WP and roll the damage again, no attack roll required.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 84),
  ('sentinel.striker.untouchable', 'path', 'Sentinel', 'Sentinel', 'Striker', 1, 'Untouchable', 'You move a heartbeat before they do. Add your Force (FOR) Trait modifier to your Evasion.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 85),
  ('sentinel.striker.concussive-combat', 'path', 'Sentinel', 'Sentinel', 'Striker', 2, 'Concussive combat', 'You have mastered the Force to aid you in battle, extending your abilities into concussive force:
Shockwave: Make a Force casting roll against an Adversary in Standard range. On a hit, you deal 1d8 SNC damage.
Concussive wave: Make a Force casting roll against all Adversaries in Close range. On a success, they each take SNC damage equal to your Sentinel Die and are knocked Prone.', 'Force Casting', '{"kind":"casting","tradition":"force"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 86),
  ('sentinel.striker.relentless-pursuit', 'path', 'Sentinel', 'Sentinel', 'Striker', 2, 'Relentless pursuit', 'When you reduce an Adversary to 0 HP, you may clear 1 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 87),
  ('sorcerer.none.conceal-or-summon-weapon', 'path', 'Sorcerer', 'Sorcerer', '', 0, 'Conceal or summon weapon', 'You may conceal any weapon you are holding, which disappears with a flash of Magickal ichor. You may summon that weapon again with the use of another manoeuvre. You may only conceal one weapon at a time.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 88),
  ('sorcerer.none.spell-of-thought-touch', 'path', 'Sorcerer', 'Sorcerer', '', 0, 'Spell of thought touch', 'You can send your thoughts and emotions to another lifeform within range. The recipient knows these thoughts and emotions are not their own but cannot determine their source.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 89),
  ('sorcerer.none.drain', 'path', 'Sorcerer', 'Sorcerer', '', 1, 'Drain', 'Make a Magick casting roll against an organic Adversary you can touch. On a success, mark off 1 additional WP, and you drain 1 HP from the target to replenish your own HP by 1.
Alternatively, no roll required, you may transfer any number of HP from yourself to another organic Hero or NPC.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 90),
  ('sorcerer.none.tome-of-peridia', 'path', 'Sorcerer', 'Sorcerer', '', 1, 'Tome of Peridia', 'Graver whisper: Mark off 1 WP to commune with lingering spirits in your immediate area. You may ask the GM one question. The spirits answer cryptically, but truthfully.
Drain essence: Touch a creature in Close range and make a Magick casting roll. On a success, mark off 1 additional WP and transfer 1 HP from the target to yourself.
The Great Mother''s chant: Mark off 1 WP and select a Hero in Near range; they clear 3 WP.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 (Graver whisper, Great Mother''s chant); 1 on success (Drain essence)', '1.2.0', 91),
  ('sorcerer.none.whispers-of-renewal', 'path', 'Sorcerer', 'Sorcerer', '', 1, 'Whispers of renewal', 'You draw on the murmur of Magick to restore your resolve. Once per Full Rest, you may perform a brief ritual or incantation, and clear WP equal to your Force (FOR) Trait modifier.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 92),
  ('sorcerer.none.curse-mark', 'path', 'Sorcerer', 'Sorcerer', '', 2, 'Curse mark', 'Make a Magick casting roll against a target in Standard range.
On a success, mark them with a brand of ichor. Until the end of your Focus, all attacks against the marked target have Advantage.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 93),
  ('sorcerer.none.steeped-in-ichor', 'path', 'Sorcerer', 'Sorcerer', '', 3, 'Steeped in ichor', 'Magick no longer resists you. Add +1 to your Magick casting rolls.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'No', 0, 'None', '1.2.0', 94),
  ('sorcerer.embalmed.arcane-resilience', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 0, 'Arcane resilience', 'Advantage on Resilience saving rolls.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 95),
  ('sorcerer.embalmed.ichor-strength', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 0, 'Ichor strength', 'Use your FOR Trait modifier in place of your STR Trait modifier.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 96),
  ('sorcerer.embalmed.chant-of-empowerment', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 1, 'Chant of empowerment', 'As a downtime move, you may perform a ritual granting you temporary might in a trait of your choice. You gain +1 on one Trait modifier of your choice until your next rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 97),
  ('sorcerer.embalmed.magickal-inevitability', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 1, 'Magickal Inevitability', 'When you fail an action roll, your next action roll has Advantage.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 98),
  ('sorcerer.embalmed.resistance', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 1, 'Resistance', 'As a Trigger move in response to being hit with an attack that does PHY damage, gain resistance to only the incoming PHY damage from that attack.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 99),
  ('sorcerer.embalmed.unearthly-attack', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 1, 'Unearthly attack', 'Ichor lends your strikes an unnatural reach. You may use a melee attack roll on two targets in range, rolling the damage separately.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 100),
  ('sorcerer.embalmed.eternal-flesh', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 2, 'Eternal flesh', 'Your body is partially immortalised through Magickal ichor:
you no longer age naturally
you are invulnerable to Poison (PSN) damage
you are immune to being Frightened.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 101),
  ('sorcerer.embalmed.spiritual-salvation', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 2, 'Spiritual salvation', 'Once per rest, a surplus of Magickal ichor manifests within you, spilling out to one other around you. You both clear 2 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 102),
  ('sorcerer.embalmed.tome-of-the-lost', 'path', 'Sorcerer', 'Sorcerer', 'Embalmed', 2, 'Tome of the Lost', 'Scream of the Ssurian: Make a Magick casting roll against targets in a 3m cone as you emit the deep thrumming vibrations of a Ssurian dragon''s hunting call. On a success, each target takes damage equal to your Sorcerer Die.
Touch of the Kiin''Dray: Mark off 1 WP; you may climb twice your speed and your grip on objects becomes unbreakable until dispelled.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 (Touch of the Kiin''Dray)', '1.2.0', 103),
  ('sorcerer.ichor-wielder.summon-weapon', 'path', 'Sorcerer', 'Sorcerer', 'Ichor wielder', 1, 'Summon weapon', 'Mark off 1 WP to summon a weapon formed from ichor appropriate to your current tier or lower. You may dissolve the weapon at no cost.
A non-exhaustive list of ichor weapons is listed in the Path archetype description.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 104),
  ('sorcerer.ichor-wielder.return-to-hand', 'path', 'Sorcerer', 'Sorcerer', 'Ichor wielder', 1, 'Return to hand', 'Your ichor always finds its way home. Throw a summoned weapon at a target within Standard range, making an attack with your Magick casting modifier. On a hit, deal the weapon''s normal damage as Ichor (ICH). The weapon dissolves and re-forms in your hand.', 'Summon weapon', '{"kind":"card","name":"Summon weapon","cardId":"sorcerer.ichor-wielder.summon-weapon"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 105),
  ('sorcerer.ichor-wielder.festering-wound', 'path', 'Sorcerer', 'Sorcerer', 'Ichor wielder', 1, 'Festering wound', 'Your ichor lingers in every cut. When you hit with a summoned weapon, the wound festers for a Countdown (4). Until the countdown ends, as a manoeuvre, mark off 1 WP to deal damage equal to your Sorcerer Die to the target as Ichor (ICH) damage. You may do this a number of times per wound equal to your Force (FOR) modifier (minimum once).', 'Summon weapon', '{"kind":"card","name":"Summon weapon","cardId":"sorcerer.ichor-wielder.summon-weapon"}'::jsonb, 'No', 1, '1 per use', '1.2.0', 106),
  ('sorcerer.ichor-wielder.ichor-detonation', 'path', 'Sorcerer', 'Sorcerer', 'Ichor wielder', 2, 'Ichor detonation', 'Once per Full Rest, when you reduce an Adversary to 0 HP, their body erupts in a burst of dark Magick. Make a casting roll against all Adversaries in Close range (3m) of the fallen target.
On a hit, each takes damage equal to your Sorcerer Die.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 107),
  ('sorcerer.ichor-wielder.ichor-shield', 'path', 'Sorcerer', 'Sorcerer', 'Ichor wielder', 2, 'Ichor shield', 'As a Trigger move in response to an incoming attack, conjure a swirling barrier of dark ichor. Add your Sorcerer Die to your Evasion for that attack.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 108),
  ('sorcerer.ichor-wielder.greater-enchant-weapon', 'path', 'Sorcerer', 'Sorcerer', 'Ichor wielder', 2, 'Greater enchant weapon', 'Mark off 2 WP to flood a weapon you''re holding with ichor. For a Countdown (6), its hits deal an additional 2d6 Ichor (ICH) damage. This does not stack with Enchant weapon.', '', 'null'::jsonb, 'No', 2, '2', '1.2.0', 109),
  ('sorcerer.shaman.force-lightning', 'path', 'Sorcerer', 'Sorcerer', 'Shaman', 1, 'Force lightning', 'Make a casting roll against a target in Far range. On a hit, mark off 1 additional WP; your lightning strikes them and you deal Lightning damage equal to your Sorcerer Die.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 110),
  ('sorcerer.shaman.ichor-bind', 'path', 'Sorcerer', 'Sorcerer', 'Shaman', 1, 'Ichor bind', 'Make a Magick casting roll against all Adversaries within Close range. If you hit at least 1 target, mark off 1 additional WP.
Targets you succeed against are temporarily Restrained as their ichor binds them in place.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 111),
  ('sorcerer.shaman.spiritual-effigy', 'path', 'Sorcerer', 'Sorcerer', 'Shaman', 1, 'Spiritual Effigy', 'Select a target you can see and mark them as your effigy; a Magickal bond is created between you. You gain the following benefits:
rolls against the effigy have Advantage
rolls against you by the effigy are made with Disadvantage
mark off 1 WP to add your Sorcerer Die to damage rolls against the effigy.', '', 'null'::jsonb, 'No', 1, '1 per damage boost', '1.2.0', 112),
  ('sorcerer.shaman.the-great-mothers-embrace', 'path', 'Sorcerer', 'Sorcerer', 'Shaman', 2, 'The Great Mother''s embrace', 'Once per Full Rest, mark off 2 WP and choose up to two allies in Standard range. Each ally clears HP equal to your Force (FOR) Trait modifier.', '', 'null'::jsonb, 'No', 2, '2', '1.2.0', 113),
  ('sorcerer.shaman.chants-of-the-green-mist', 'path', 'Sorcerer', 'Sorcerer', 'Shaman', 2, 'Chants of the Green Mist', 'A Nightsister chant-book, its pages stained with old ichor. You gain the following:
Hex of ill luck: make a Magick casting roll against an Adversary within Standard range. On a success, mark off 1 additional WP; its next attack is made with Disadvantage.
Spirit ward: as a manoeuvre, mark off 1 WP to ward a doorway or an area within Near range. You know when it is crossed, and the first creature through takes damage equal to your Sorcerer Die as Ichor (ICH) damage. The ward fades at your next rest.
Spirit messenger: send a short spectral whisper to an ally anywhere on the same planet.', 'Magick Casting', '{"kind":"casting","tradition":"magick"}'::jsonb, 'Yes', 1, '1 on success (Hex of ill luck); 1 (Spirit ward)', '1.2.0', 114),
  ('technologist.none.gc-47-10029', 'path', 'Technologist', 'Technologist', '', 0, 'GC-47-10029', 'A field-operations datapack, standard issue for survey engineers. Loading it upgrades your Basic Tech powers:
Perimeter net (upgrades Alarm): Set up to three alarms at once. When one trips, you know which, and roughly what tripped it.
Holo-decoy (upgrades Lesser hologram): Mark off 1 WP to project a moving, life-size hologram of a person or object within Standard range, for a Countdown (4) or until touched. An Adversary that attacks the decoy wastes that attack.
Flashpoint (upgrades Light): Mark off 1 WP to flare your light. Adversaries within Close range have Disadvantage on their next attack.
Life-sign scan: Detect life signs through walls and doors within Near range, learning their number and rough size.', 'Basic Tech powers', '{"kind":"card","name":"Basic Tech powers","cardId":"tech-casting.none.basic-tech-powers"}'::jsonb, 'No', 1, '1 (Holo-decoy, Flashpoint)', '1.2.0', 115),
  ('technologist.none.raa-4430211', 'path', 'Technologist', 'Technologist', '', 0, 'RAA-4430211', 'Loading this item grants you the following:
you are able to repair any droid you can touch. Mark off 1 WP to grant the droid 1 HP
you are able to enhance a droid you can touch, granting it your Technologist Die on its next action or attack roll
make a Tech casting roll at a droid target. On a success, mark off 1 additional WP and the droid target is disabled until the GM spends Despair (or similar means) to reactivate it.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 1, '1 (repair); 1 on success (disable)', '1.2.0', 116),
  ('technologist.none.bacta-patches', 'path', 'Technologist', 'Technologist', '', 1, 'Bacta patches', 'You are able to produce healing patches which can be applied to any organics you can touch.
On application, the recipient clears 1 HP. You can do this a number of times equal to your Intelligence (INT) Trait modifier.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 117),
  ('technologist.none.data-spike', 'path', 'Technologist', 'Technologist', '', 1, 'Data spike', 'You are able to plug into an attempt to hijack a computer system or droid, programming in simple commands or accessing low-security systems.
Make a Tech casting roll to break into a system.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 118),
  ('technologist.none.system-reboot', 'path', 'Technologist', 'Technologist', '', 1, 'System reboot', 'You run a quick diagnostic on your tech pad and reset your mental state alongside it.
Once per Short Rest, clear 1 WP. If you do this while tending to a droid ally, they also clear 1 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 119),
  ('technologist.none.micro-ordnance-launcher', 'path', 'Technologist', 'Technologist', '', 2, 'Micro-ordnance launcher', 'A precision-engineered launcher built into your gear: compact, brutal, and endlessly customisable. When you fire, make a Tech casting roll against a single target in Standard range. On a hit, the round delivers its payload. Before rolling, you may mark off additional WP to increase the damage; each additional WP adds +1d4 to the round''s damage. Choose one ordnance type when you take this feature:
Acid round: Deals 1d4 Poison (PSN) damage
Carbonite round: Deals 1d4 Cold (CLD) damage
Corrosive round: Droid targets only. Deals 1d4 Physical (PHY) damage and the target gains the Weakened condition. No effect on organics
Explosive round: Deals 1d4 Fire (FIR) damage
Toxic round: Organic targets only. Deals 1d4 Poison (PSN) damage and the target gains the Weakened condition. No effect on droids.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', null, 'Optional: 1 per +1d4', '1.2.0', 120),
  ('technologist.none.quick-refit', 'path', 'Technologist', 'Technologist', '', 2, 'Quick refit', 'You can patch plating with your eyes closed. Once per Short Rest, as a manoeuvre, without marking WP, restore one Armour Slot to yourself or an ally you can touch.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 121),
  ('technologist.none.defensive-protocols', 'path', 'Technologist', 'Technologist', '', 3, 'Defensive protocols', 'As a Trigger move in response to an incoming attack against an ally in Standard range, project a temporary energy shield from your tech pad.
Reduce the incoming damage by your Technologist Die.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 122),
  ('technologist.none.overclocked-conduit', 'path', 'Technologist', 'Technologist', '', 3, 'Overclocked conduit', 'Your Tech Conduit runs hotter than the manufacturer ever intended. Add +1 to your Tech casting rolls.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'No', 0, 'None', '1.2.0', 123),
  ('technologist.artillerist.heavy-ordnance', 'path', 'Technologist', 'Technologist', 'Artillerist', 1, 'Heavy ordnance', 'As a downtime move, you may craft a number of grenades equal to your Intelligence (INT) Trait modifier:
grenades can deal different damage types, either Fire (FIR), Ion (ION) or Physical (PHY)
each grenade explosion deals Technologist Die x 2 damage
grenades expire by your next Full Rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 124),
  ('technologist.artillerist.incendiary-array', 'path', 'Technologist', 'Technologist', 'Artillerist', 1, 'Incendiary array', 'Your tech pad is rigged with a suite of fire-based weaponry, built to burn. Choose one of the following attacks:
Flame jet: Unleash a searing cone of fire at Near range (3m). Make a Tech casting roll against all targets in the cone. On a hit, deal 1d6 Fire (FIR) damage
Thermal barrage: Launch a concentrated blast at a single target within Standard range. Make a Tech casting roll. On a hit, deal 1d8 Fire (FIR) damage
Sweeping blaze: Arc a wave of flame across the battlefield. Make a Tech casting roll against all targets in a Near range (3m) radius. On a hit, deal 1d4 Fire (FIR) damage.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 125),
  ('technologist.artillerist.suppressive-fire', 'path', 'Technologist', 'Technologist', 'Artillerist', 1, 'Suppressive fire', 'When you or your turret attack, impose Disadvantage on the target''s next attack roll.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 126),
  ('technologist.artillerist.turret-overdrive', 'path', 'Technologist', 'Technologist', 'Artillerist', 1, 'Turret overdrive', 'Your turret may attack twice when the countdown is triggered.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 127),
  ('technologist.artillerist.turret-upgrades', 'path', 'Technologist', 'Technologist', 'Artillerist', 2, 'Turret upgrades', 'Your turret finally gets the attention it deserves. Choose two upgrades when you take this card:
Repulsor legs: as a manoeuvre, without marking WP, move your turret up to Standard range
Reinforced plating: your turret gains 1 additional HP slot, and its Minor threshold doubles
Ion rounds: your turret deals Ion (ION) damage, and droids it hits are Ionised.', 'Deployable turret', '{"kind":"archetype_feature","name":"Deployable turret","featureKey":"technologist/artillerist:deployable-turret"}'::jsonb, 'No', 0, 'None', '1.2.0', 128),
  ('technologist.artillerist.mortar-strike', 'path', 'Technologist', 'Technologist', 'Artillerist', 2, 'Mortar strike', 'Make a Tech casting roll against every Adversary within 3 m of a point you can see within Standard range. On a success, mark off 1 additional WP; each affected Adversary takes damage equal to your Technologist Die × 2 as Physical (PHY) damage.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 129),
  ('technologist.polestar.eyes-everywhere', 'path', 'Technologist', 'Technologist', 'Polestar', 0, 'Eyes everywhere', 'Attacks against you from Hidden Adversaries do not have Advantage.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 130),
  ('technologist.polestar.pinpoint-the-weakness', 'path', 'Technologist', 'Technologist', 'Polestar', 1, 'Pinpoint the weakness', 'When you mark a target as tracked, mark off 1 WP. You learn the target''s Difficulty score and one resistance or vulnerability.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 131),
  ('technologist.polestar.spotter', 'path', 'Technologist', 'Technologist', 'Polestar', 1, 'Spotter', 'As a Trigger move in response to an ally making an attack, you may give them Advantage. You can do this a number of times per rest equal to your Intelligence (INT) modifier.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 132),
  ('technologist.polestar.threat-anticipation', 'path', 'Technologist', 'Technologist', 'Polestar', 1, 'Threat anticipation', 'You read the field before it reads you. You gain the following:
Predictive screen: As a Trigger move in response to an incoming attack, you may mark off 1 additional WP to project a flickering deflector pattern your tech pad mapped half a heartbeat early. Reduce the incoming attack''s damage by two thresholds.
Snare beacon: You fire a homing micro-tether from your tech pad, latching onto a target and pinning them to the nearest surface. Make a Tech casting roll against a target. On a success, the target becomes Immobilised.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 2, '2 (Predictive screen: Trigger + 1 additional)', '1.2.0', 133),
  ('technologist.polestar.pathfinder-survey-datapack', 'path', 'Technologist', 'Technologist', 'Polestar', 2, 'Pathfinder survey datapack', 'Standard issue for scouts charting the edges of known space. Loading it grants you the following:
Heat scan: as a manoeuvre, mark off 1 WP to sweep your Tech Conduit across Standard range. You detect the heat signature of every creature and powered droid within it, including Hidden ones, and learn where each one is.
Shared lock: your Tracked target can''t benefit from the Hidden condition against you or any ally within Far range of you.
Jump plot: when you plot a hyperspace route, make the Astrogation roll with Advantage. On a success, the journey takes half the usual time.', 'Targeted navigator', '{"kind":"archetype_feature","name":"Targeted navigator","featureKey":"technologist/polestar:targeted-navigator"}'::jsonb, 'No', 1, '1 (Heat scan)', '1.2.0', 134),
  ('technologist.polestar.run-them-down', 'path', 'Technologist', 'Technologist', 'Polestar', 2, 'Run them down', 'Once you have their scent, they can''t shake you. Against your Tracked target, you gain the following:
Advantage on rolls to chase, track or find it
as a Trigger move in response to it moving away from you, move up to Standard range towards it without making an Athletics roll.', 'Targeted navigator', '{"kind":"archetype_feature","name":"Targeted navigator","featureKey":"technologist/polestar:targeted-navigator"}'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 135),
  ('technologist.safety-net.brace', 'path', 'Technologist', 'Technologist', 'Safety Net', 1, 'Brace', 'When you mark off an Armour Slot to reduce incoming damage, you can mark off 1 WP to mark off an additional Armour Slot.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 136),
  ('technologist.safety-net.field-medic', 'path', 'Technologist', 'Technologist', 'Safety Net', 1, 'Field medic', 'You always carry what your crew needs to stay in the fight. Mark off 1 WP and inject an organic Hero in Close range with one of the following stims:
Adrenaline stim: A jolt of pure energy surges through your ally. Roll 1d4; the target clears that much WP
Healing stim: Bacta-laced nano-gel floods the wound. Roll 1d4; the target clears that much HP
Cleansing stim: A cocktail of anti-venoms and stabilisers purges the system. Clear any one condition from the target, except Dying or Unconscious.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 137),
  ('technologist.safety-net.reassurance', 'path', 'Technologist', 'Technologist', 'Safety Net', 1, 'Reassurance', 'Once per rest, you utter words of reassurance to someone. They clear 2 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 138),
  ('technologist.safety-net.systems-engineer', 'path', 'Technologist', 'Technologist', 'Safety Net', 1, 'Systems engineer', 'You know every circuit and power relay by heart. Mark off 1 WP and interface with a droid Hero in Close range to perform one of the following:
Energy surge: You reroute reserve power through the droid''s core. Roll 1d4; the target clears that much WP
Rapid patch: You bypass damaged components and restore function. Roll 1d4; the target clears that much HP
Diagnostics sweep: You run a full system scan and purge corrupted data. Clear any one condition from the target, except Dying or Unconscious.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 139),
  ('technologist.safety-net.emergency-recall', 'path', 'Technologist', 'Technologist', 'Safety Net', 2, 'Emergency recall', 'Your Tech Conduit locks onto an ally and pulls them out of harm''s way. As a Trigger move in response to an ally within Standard range being targeted by an attack, mark off 1 additional WP. Before the GM determines hit or miss, the ally gains +5 Evasion against that attack, and you then teleport them to a space you can see within Standard range of where they stood.', '', 'null'::jsonb, 'No', 2, '2 (Trigger + 1 additional)', '1.2.0', 140),
  ('technologist.safety-net.field-armourer', 'path', 'Technologist', 'Technologist', 'Safety Net', 2, 'Field armourer', 'You keep the crew''s armour patched mid-fight. As a manoeuvre, mark off 1 WP to restore one Armour Slot to an ally you can touch. You may do this a number of times per Short Rest equal to your Intelligence (INT) modifier (minimum once).', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 141),
  ('technologist.skeleton-key.run-the-building', 'path', 'Technologist', 'Technologist', 'Skeleton Key', 1, 'Run the building', 'Once you''re in, the place answers to you. While you control a system through Security Spike, you may do any of the following within it as a manoeuvre, without marking WP:
open, lock or seal doors
loop or blind cameras and sensors
trigger or silence alarms.', 'Security spike', '{"kind":"archetype_feature","name":"Security spike","featureKey":"technologist/skeleton-key:security-spike"}'::jsonb, 'No', 0, 'None', '1.2.0', 142),
  ('technologist.skeleton-key.refraction-field', 'path', 'Technologist', 'Technologist', 'Skeleton Key', 1, 'Refraction field', 'Your Tech Conduit bends light around you. When you Hide, you may make a Tech casting roll in place of an Agility (Stealth) roll, and you may attempt to Hide even while an Adversary can see you. On a success, mark off 1 additional WP.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 143),
  ('technologist.skeleton-key.backdoor', 'path', 'Technologist', 'Technologist', 'Skeleton Key', 1, 'Backdoor', 'Every lock has a weakness, and you know where to look. You gain the following:
you have Advantage on Skulduggery rolls to pick locks and bypass physical security
when you begin a Security Spike Ritual, add your Technologist Die to the progress from your first roll.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 144),
  ('technologist.skeleton-key.sk-1138-spike-library', 'path', 'Technologist', 'Technologist', 'Skeleton Key', 2, 'SK-1138 spike library', 'A slicer''s library of spikes, worms and forgeries, traded in whispers across the Outer Rim. Loading it grants you the following:
Ghost loop: make a Tech casting roll to loop a camera or sensor you can see, without beginning a Security Spike Ritual. On a success, it shows nothing amiss for a Countdown (6).
Worm: when you complete a Security Spike Ritual, you also gain control of one system connected to it, without a further Ritual.
Forger''s script: as a downtime move, forge a credential or ID chip that passes a casual scan. Close inspection calls for a Deception roll against the inspector''s Difficulty.', 'Security spike', '{"kind":"archetype_feature","name":"Security spike","featureKey":"technologist/skeleton-key:security-spike"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 145),
  ('technologist.skeleton-key.instant-translocate', 'path', 'Technologist', 'Technologist', 'Skeleton Key', 2, 'Instant translocate', 'As a Trigger move in response to being targeted by an attack, mark off 1 additional WP. Before the GM determines hit or miss, add +5 to your Evasion against that attack, then teleport to a space you can see within Standard range. If the attack misses, you may make one attack against the attacker with Advantage.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Conditional', 2, '2 (Trigger + 1 additional)', '1.2.0', 146),
  ('technologist.skeleton-key.mislead', 'path', 'Technologist', 'Technologist', 'Skeleton Key', 2, 'Mislead', 'Your Tech Conduit throws a perfect hologram of you while bending light around your real body. As a manoeuvre, mark off 2 WP. You gain the Hidden condition at the same moment a holographic double of you appears where you are standing. The double lasts for a Countdown (6), but your Hidden condition ends if you attack or cast a power. You gain the following:
as a manoeuvre, move the double up to Far range and make it gesture, speak and behave however you choose
as a manoeuvre, switch between your own senses and the double''s. While using its senses, you see and hear as if you were standing where it is, but you can''t see or hear your own surroundings.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'No', 2, '2', '1.2.0', 147),
  ('wayfarer.none.gc-47-10029', 'path', 'Wayfarer', 'Wayfarer', '', 0, 'GC-47-10029', 'A field-operations datapack, lifted from a survey crew who won''t miss it. Loading it upgrades your Basic Tech powers:
Perimeter net (upgrades Alarm): Set up to three alarms at once. When one trips, you know which, and roughly what tripped it.
Holo-decoy (upgrades Lesser hologram): Mark off 1 WP to project a moving, life-size hologram of a person or object within Standard range, for a Countdown (4) or until touched. An Adversary that attacks the decoy wastes that attack.
Flashpoint (upgrades Light): Mark off 1 WP to flare your light. Adversaries within Close range have Disadvantage on their next attack.
Life-sign scan: Detect life signs through walls and doors within Near range, learning their number and rough size.', 'Basic Tech powers', '{"kind":"card","name":"Basic Tech powers","cardId":"tech-casting.none.basic-tech-powers"}'::jsonb, 'No', 1, '1 (Holo-decoy, Flashpoint)', '1.2.0', 148),
  ('wayfarer.none.weapon-stabilisation', 'path', 'Wayfarer', 'Wayfarer', '', 0, 'Weapon stabilisation', 'Mark off 1 WP to get Advantage on your next ranged weapon attack roll.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 149),
  ('wayfarer.none.loaded-darts', 'path', 'Wayfarer', 'Wayfarer', '', 1, 'Loaded darts', 'Your gauntlet houses a concealed dart launcher: small, silent, and deadly. When you fire a dart, make a Tech casting roll against a single target in Standard range. On a hit, mark off 1 additional WP and the dart delivers its payload. Before rolling, you may mark off additional WP to increase the damage; each additional WP adds +1d4 to the dart''s damage. Choose one dart type when you take this feature:
Acid dart: Deals 1d4 Poison (PSN) damage
Carbonite dart: Deals 1d4 Cold (CLD) damage
Corrosive dart: Droid targets only. Deals 1d4 Physical (PHY) damage and the target gains the Weakened condition. No effect on organics
Explosive dart: Deals 1d4 Fire (FIR) damage
Toxic dart: Organic targets only. Deals 1d4 Poison (PSN) damage and the target gains the Weakened condition. No effect on droids.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 1, '1 on success; optional extra 1 per +1d4', '1.2.0', 150),
  ('wayfarer.none.luck-of-the-draw', 'path', 'Wayfarer', 'Wayfarer', '', 1, 'Luck of the draw', 'Reroll any 1s or 2s on action rolls. You may not reroll double 1s.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 151),
  ('wayfarer.none.never-tell-me-the-odds', 'path', 'Wayfarer', 'Wayfarer', '', 1, 'Never tell me the odds', 'Against all reason, you thrive under pressure. Once per Full Rest, when you have 2 or fewer WP remaining, immediately clear 3 WP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 152),
  ('wayfarer.none.pyro-rig', 'path', 'Wayfarer', 'Wayfarer', '', 1, 'Pyro rig', 'Your tech pad crackles with volatile energy; time to light things up. Choose one of the following attacks:
Jet of flame: Unleash a searing cone of fire at Near range (3m). Make a Tech casting roll against all targets in the cone. On a hit, deal 1d6 Fire (FIR) damage.
Thermal blast: Hurl a volatile charge at a single target within Standard range. Make a Tech casting roll. On a hit, deal 1d8 Fire (FIR) damage.
Arcing jet: Launch a curving stream of flame that sweeps across the battlefield. Make a single Tech casting roll against all targets in a Near range (3m) radius. On a hit, deal 1d4 Fire (FIR) damage.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 0, 'None', '1.2.0', 153),
  ('wayfarer.none.quick-shots', 'path', 'Wayfarer', 'Wayfarer', '', 1, 'Quick shots', 'You may use a ranged attack roll on two targets in range, rolling the damage separately.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 154),
  ('wayfarer.none.light-on-your-feet', 'path', 'Wayfarer', 'Wayfarer', '', 2, 'Light on your feet', 'You''re hardest to hit when you''re travelling light. While you wear light armour or none, add +1 to your Evasion.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 155),
  ('wayfarer.none.steady-aim', 'path', 'Wayfarer', 'Wayfarer', '', 2, 'Steady aim', 'Years of shootouts have steadied your hand. Add +1 to your attack rolls with blasters.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 156),
  ('wayfarer.gunslinger.deadeye', 'path', 'Wayfarer', 'Wayfarer', 'Gunslinger', 1, 'Deadeye', 'When you have Advantage on an attack with a blaster:
you may rapid-fire, unleashing shots equal to your Agility (AGI) Trait modifier, making a single attack roll for all shots
on a success, mark off 1 additional WP and the target takes full damage for each shot. On a failure, the target takes normal damage.', '', 'null'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 157),
  ('wayfarer.gunslinger.defensive-measures', 'path', 'Wayfarer', 'Wayfarer', 'Gunslinger', 1, 'Defensive measures', 'You are prepared for the worst. You gain the following:
Energy shield: As a Trigger move in response to an incoming attack, you may mark off 1 additional WP to activate an energy shield, reducing the incoming attack''s damage by two thresholds
Wire bind: You produce a thread of wire from your tech pad. Make a Tech casting roll against a target. On a success, mark off 1 additional WP and the target becomes Immobilised.', 'Tech Casting', '{"kind":"casting","tradition":"tech"}'::jsonb, 'Yes', 2, '2 (Energy shield: Trigger + 1 additional); 1 on success (Wire bind)', '1.2.0', 158),
  ('wayfarer.gunslinger.quickfire-opportunist', 'path', 'Wayfarer', 'Wayfarer', 'Gunslinger', 1, 'Quickfire opportunist', 'Whenever you have Advantage on an attack roll you may do the following:
you may unleash a round of shots equal to your Agility (AGI) Trait modifier
make a single attack roll with Advantage against all the targets
roll the damage for each shot that hits.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 159),
  ('wayfarer.gunslinger.call-out', 'path', 'Wayfarer', 'Wayfarer', 'Gunslinger', 2, 'Call out', 'You name your opponent and everyone else gets out of the way. As a manoeuvre, mark off 1 WP to call out an Adversary within Standard range. Until you next take the Focus, you have Advantage on ranged attacks against it, and it has Disadvantage on attacks against anyone but you.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 160),
  ('wayfarer.gunslinger.point-blank', 'path', 'Wayfarer', 'Wayfarer', 'Gunslinger', 2, 'Point blank', 'Distance is for amateurs. You ignore any Disadvantage on ranged attacks from being within Close range of an Adversary. When you make a Quick fingered shot, you may mark off 1 additional WP to make it with Advantage.', 'Quick fingered', '{"kind":"archetype_feature","name":"Quick fingered","featureKey":"wayfarer/gunslinger:quick-fingered"}'::jsonb, 'No', 1, '1 additional per boosted shot', '1.2.0', 161),
  ('wayfarer.operative.feint', 'path', 'Wayfarer', 'Wayfarer', 'Operative', 1, 'Feint', 'A dropped shoulder, a glance away, and they bite. Make an Agility (Skulduggery) or Presence (Deception) roll against an Adversary within Close range. On a success, your next attack against it has Advantage. If the roll succeeds with Balance, the next ally to attack it also has Advantage.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 162),
  ('wayfarer.operative.vanish', 'path', 'Wayfarer', 'Wayfarer', 'Operative', 1, 'Vanish', 'Strike, then gone. When you hit with an attack that had Advantage, you may immediately make an Agility (Stealth) roll to Hide, even if Adversaries can see you. On a success, mark off 1 additional WP.', '', 'null'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 163),
  ('wayfarer.operative.sabotage-charges', 'path', 'Wayfarer', 'Wayfarer', 'Operative', 1, 'Sabotage charges', 'As a downtime move, prepare a number of charges equal to your proficiency bonus. As a manoeuvre, plant one on an object or surface within Close range. If an Adversary is watching, make an Agility (Skulduggery) roll against its Difficulty to do it unseen. As a Trigger move, detonate a charge you can see, choosing one effect:
Breach: destroy a door, lock, console or vehicle system
Burn: deal 2d6 Fire (FIR) damage to each creature within Close range of the charge
Blind: smoke fills Near range of the charge, making it Heavily Obscured for a Countdown (4)
Unused charges expire at your next Full Rest.', '', 'null'::jsonb, 'Conditional', 1, '1 per detonation (Trigger)', '1.2.0', 164),
  ('wayfarer.operative.opening', 'path', 'Wayfarer', 'Wayfarer', 'Operative', 2, 'Opening', 'You strike through the gap your allies make. When an ally hits an Adversary within Close range of you, your next attack against that Adversary has Advantage.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 165),
  ('wayfarer.operative.toxin-kit', 'path', 'Wayfarer', 'Wayfarer', 'Operative', 2, 'Toxin kit', 'As a downtime move, prepare a number of toxin doses equal to your proficiency bonus. When you hit an organic Adversary with an attack, you may expend a dose: it gains the Weakened condition and takes 1d6 Poison (PSN) damage on a Countdown (4). Unused doses expire at your next Full Rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 166),
  ('vanguard.none.first-look', 'path', 'Vanguard', 'Vanguard', '', 0, 'First Look', 'You read a room before you walk into it. Once per Short Rest, when you enter a new place or encounter, ask the GM one of the following and they must answer honestly:
Who holds the power here?
What is the biggest threat?
Where is the way out?', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 167),
  ('vanguard.none.steady-read', 'path', 'Vanguard', 'Vanguard', '', 1, 'Steady Read', 'Your reads hold under pressure. Your Assess stances last for a Countdown (6) instead of 4, and only Massive damage ends them early.', 'Assess', '{"kind":"path_feature","name":"Assess"}'::jsonb, 'No', 0, 'None', '1.2.0', 168),
  ('vanguard.none.formation', 'path', 'Vanguard', 'Vanguard', '', 2, 'Formation', 'Your allies move as one around you. While one of your Assess stances is active, allies within Near range add +1 to their Evasion and have Advantage on saving rolls against the Frightened condition.', 'Assess', '{"kind":"path_feature","name":"Assess"}'::jsonb, 'No', 0, 'None', '1.2.0', 169),
  ('vanguard.none.twin-read', 'path', 'Vanguard', 'Vanguard', '', 3, 'Twin Read', 'You see the whole situation at once. Once per Full Rest, when you Assess, you may hold two stances at the same time without marking WP for a second use.', 'Assess', '{"kind":"path_feature","name":"Assess"}'::jsonb, 'No', 1, '1 (Assess)', '1.2.0', 170),
  ('vanguard.spearhead.kitted-for-the-front', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 1, 'Kitted for the Front', 'You go in first, so you go in armed. You gain proficiency with all blasters and all physical weapons.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 171),
  ('vanguard.spearhead.follow-me', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 1, 'Follow Me', 'Mark off 1 WP when you take the Focus. You and a number of allies within Near range equal to your Presence (PRE) modifier (minimum 1) move up to Far range without making Athletics rolls, ending within Close range of you.', '', 'null'::jsonb, 'No', 1, '1', '1.2.0', 172),
  ('vanguard.spearhead.lead-from-the-front', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 1, 'Lead from the Front', 'When an ally succeeds with Balance on a roll that Lead by Example gave Advantage to, they clear 1 additional WP.', 'Lead by Example', '{"kind":"archetype_feature","name":"Lead by Example","featureKey":"vanguard/spearhead:lead-by-example"}'::jsonb, 'No', 0, 'None', '1.2.0', 173),
  ('vanguard.spearhead.second-chance', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 2, 'Second Chance', 'You may use Step In a number of times per Short Rest equal to your Presence (PRE) modifier (minimum once).', 'Step In', '{"kind":"archetype_feature","name":"Step In","featureKey":"vanguard/spearhead:step-in"}'::jsonb, 'No', 2, '2 per Step In use (Trigger + 1 additional)', '1.2.0', 174),
  ('vanguard.spearhead.draw-their-fire', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 2, 'Draw Their Fire', 'As a Trigger move in response to an ally within Near range being targeted by an attack, become the target instead. Add your Presence (PRE) modifier to your Evasion against that attack.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 175),
  ('vanguard.spearhead.shoulder-to-shoulder', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 2, 'Shoulder to Shoulder', 'You and your allies cover each other. As a Trigger move in response to you or an ally within Close range of you taking damage, reduce the damage by one threshold.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 176),
  ('vanguard.spearhead.inspiring-victory', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 3, 'Inspiring Victory', 'As a Trigger move in response to reducing an Adversary to 0 HP, allies within Near range who can see you clear 1 WP. You may use this feature a number of times per Full Rest equal to your Presence (PRE) modifier (minimum once).', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 177),
  ('vanguard.spearhead.unbroken', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 3, 'Unbroken', 'When a Hold the Line Countdown ends, each ally it protected clears 1 HP.', 'Hold the Line', '{"kind":"archetype_feature","name":"Hold the Line","featureKey":"vanguard/spearhead:hold-the-line"}'::jsonb, 'No', 0, 'None', '1.2.0', 178),
  ('vanguard.spearhead.breach', 'path', 'Vanguard', 'Vanguard', 'Spearhead', 3, 'Breach', 'Mark off 2 WP to lead the charge. You and every ally within Near range may each immediately make one attack against a target in reach, without marking WP, before the Focus moves on. You may do this a number of times per Full Rest equal to your Presence (PRE) modifier (minimum once).', '', 'null'::jsonb, 'Yes', 2, '2', '1.2.0', 179),
  ('vanguard.lifeline.combat-stims', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 1, 'Combat Stims', 'As a downtime move, prepare a number of stims equal to your Intelligence (INT) modifier (minimum 1). As a manoeuvre, inject an ally you can touch to clear 1 WP, or to end the Frightened or Weakened condition. Unused stims expire at your next Full Rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 180),
  ('vanguard.lifeline.triage-eye', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 1, 'Triage Eye', 'You always know how much HP and WP the allies you can see have marked, and any conditions affecting them. You have Advantage on Medicine rolls.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 181),
  ('vanguard.lifeline.well-stocked', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 1, 'Well Stocked', 'You never run short of supplies. You gain additional uses of Patch Up per Short Rest equal to your proficiency bonus.', 'Patch Up', '{"kind":"archetype_feature","name":"Patch Up","featureKey":"vanguard/lifeline:patch-up"}'::jsonb, 'No', 0, 'None', '1.2.0', 182),
  ('vanguard.lifeline.field-surgery', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 2, 'Field Surgery', 'When you use the Tend to Wounds downtime move on an ally during a Short Rest, they also clear all conditions except Dying, and clear 2 additional HP.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 183),
  ('vanguard.lifeline.adrenal-boost', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 2, 'Adrenal Boost', 'When you Patch Up an ally, you may mark off 1 additional WP. They have Advantage on their next action roll.', 'Patch Up', '{"kind":"archetype_feature","name":"Patch Up","featureKey":"vanguard/lifeline:patch-up"}'::jsonb, 'No', 1, '1 additional (on top of Patch Up''s 1)', '1.2.0', 184),
  ('vanguard.lifeline.under-fire', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 2, 'Under Fire', 'You do not trigger Adversaries'' Trigger moves when you move towards an ally who is Dying or on their last HP. While within Close range of that ally, add +2 to your Evasion.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 185),
  ('vanguard.lifeline.bacta-veteran', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 3, 'Bacta Veteran', 'When Patch Up clears HP, it clears 2 instead of 1.', 'Patch Up', '{"kind":"archetype_feature","name":"Patch Up","featureKey":"vanguard/lifeline:patch-up"}'::jsonb, 'No', 0, 'None', '1.2.0', 186),
  ('vanguard.lifeline.mass-triage', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 3, 'Mass Triage', 'Once per Short Rest, mark off 2 WP. Every ally within Near range clears 1 HP and 1 condition, except Dying or Unconscious.', '', 'null'::jsonb, 'No', 2, '2', '1.2.0', 187),
  ('vanguard.lifeline.second-life', 'path', 'Vanguard', 'Vanguard', 'Lifeline', 3, 'Second Life', 'You may use Not On My Watch a number of times per Short Rest equal to your Intelligence (INT) modifier (minimum once).', 'Not On My Watch', '{"kind":"archetype_feature","name":"Not On My Watch","featureKey":"vanguard/lifeline:not-on-my-watch"}'::jsonb, 'No', 1, '1 per Not On My Watch use (Trigger)', '1.2.0', 188),
  ('vanguard.spymaster.cover-identity', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 1, 'Cover Identity', 'You keep a false identity, with papers that hold up to scrutiny. You have Advantage on Deception rolls to maintain it, and searches of records for your real name come up empty.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 189),
  ('vanguard.spymaster.wired', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 1, 'Wired', 'As a manoeuvre, plant a listening device on a person or object you can touch. If the target is aware of you, make a Skulduggery roll against their Difficulty. Until your next Full Rest, you hear everything said within Near range of the device. You may have one device planted at a time.', '', 'null'::jsonb, 'Conditional', 0, 'None', '1.2.0', 190),
  ('vanguard.spymaster.read-the-tells', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 1, 'Read the Tells', 'You are proficient in Insight (Expertise if already proficient). The first honest question you ask with each Assess: Weakness costs no WP.', 'Assess', '{"kind":"path_feature","name":"Assess"}'::jsonb, 'No', 0, 'None', '1.2.0', 191),
  ('vanguard.spymaster.profile', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 2, 'Profile', 'Study an NPC or Adversary and make an Insight roll against their Difficulty. On a success, you infer their disposition, character and nature, and you have Advantage on Negotiation rolls against them until your next rest.', '', 'null'::jsonb, 'Yes', 0, 'None', '1.2.0', 192),
  ('vanguard.spymaster.counter-intelligence', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 2, 'Counter-intelligence', 'Adversaries can''t benefit from the Hidden condition against you. You have Advantage on Perception rolls to notice surveillance, tails or listening devices.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 193),
  ('vanguard.spymaster.whisper-network', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 2, 'Whisper Network', 'Allies who can hear you have Advantage on Deception and Insight rolls against any NPC you have asked an honest question about since your last rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 194),
  ('vanguard.spymaster.burn-notice', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 3, 'Burn Notice', 'Once per Full Rest, mark off 2 WP to expose a named Adversary''s secret to its allies. For a Countdown (4), its allies will not help it, protect it or follow its orders. If you have no real secret, you may fabricate one by making a Deception roll against the Adversary''s Difficulty; on a failure, the WP is spent and nothing happens.', '', 'null'::jsonb, 'Conditional', 2, '2', '1.2.0', 195),
  ('vanguard.spymaster.ghost-protocol', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 3, 'Ghost Protocol', 'You leave no trace in records or on sensors. Influence, and any ability that reads your intentions or motives, automatically fails against you.', 'Nothing is hidden', '{"kind":"archetype_feature","name":"Nothing is hidden","featureKey":"vanguard/spymaster:nothing-is-hidden"}'::jsonb, 'No', 0, 'None', '1.2.0', 196),
  ('vanguard.spymaster.checkmate', 'path', 'Vanguard', 'Vanguard', 'Spymaster', 3, 'Checkmate', 'Once per Full Rest, as a Trigger move in response to an Adversary about to take the Focus, reveal that you saw it coming. It loses that action, and the Focus passes to you.', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 197),
  ('vanguard.academic.polyglot', 'path', 'Vanguard', 'Vanguard', 'Academic', 1, 'Polyglot', 'Linguist. You learn languages the way others learn names. After a Short Rest spent studying a spoken or written language, you understand it, and can make yourself understood in it, however crudely.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 198),
  ('vanguard.academic.excavators-eye', 'path', 'Vanguard', 'Vanguard', 'Academic', 1, 'Excavator''s Eye', 'Archaeologist. You have Advantage on History and Investigation rolls involving ruins, relics and ancient technology. At a glance, you can tell whether a relic is genuine, trapped or still active.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 199),
  ('vanguard.academic.field-snares', 'path', 'Vanguard', 'Vanguard', 'Academic', 1, 'Field Snares', 'You know how to rig a trap from whatever is lying around. As a downtime move, craft a number of snares equal to your Intelligence (INT) modifier (minimum 1). As a manoeuvre, set one in a space within Close range; it stays hidden until triggered. When an Adversary enters it, make a Survival or Technology roll against its Difficulty. On a success, mark off 1 additional WP and apply the snare''s effect:
Noose: the Adversary is Immobilised until it takes the Focus and breaks free
Tripwire: the Adversary is knocked Prone
Alarm: you and your allies are alerted, wherever you are
Unused snares fall apart at your next Full Rest.', '', 'null'::jsonb, 'Yes', 1, '1 on success', '1.2.0', 200),
  ('vanguard.academic.field-guide', 'path', 'Vanguard', 'Vanguard', 'Academic', 1, 'Field Guide', 'Xenobiologist. You are proficient in Animal Handling. When your Field Notes briefing covers Animal Handling or Survival, allies also have Advantage on their first roll with it against a creature.', 'Field Notes', '{"kind":"archetype_feature","name":"Field Notes","featureKey":"vanguard/academic:field-notes"}'::jsonb, 'No', 0, 'None', '1.2.0', 201),
  ('vanguard.academic.gnost-durals-codex', 'path', 'Vanguard', 'Vanguard', 'Academic', 1, 'Gnost-Dural''s Codex', 'A copy of the old Jedi historian''s journal, its margins crowded with notes from every scholar who has carried it since. You gain the following:
Rigorous: You can never have Disadvantage on History or Investigation rolls made to study or research.
Sceptical insight: You can never have Disadvantage on Insight rolls to tell whether someone is lying, and you always know when a claim contradicts something you have studied.
Quick study: Once per Full Rest, after watching someone use a skill or tool for a Short Rest, you count as trained in it until your next Full Rest.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 202),
  ('vanguard.academic.peer-review', 'path', 'Vanguard', 'Vanguard', 'Academic', 2, 'Peer Review', 'As a Trigger move in response to an ally failing an Astrogation, History, Investigation, Medicine or Technology roll, let them reroll it, using your modifier if it is higher. You may do this a number of times per Short Rest equal to your Intelligence (INT) modifier (minimum once).', '', 'null'::jsonb, 'No', 1, '1 (Trigger)', '1.2.0', 203),
  ('vanguard.academic.relic-handling', 'path', 'Vanguard', 'Vanguard', 'Academic', 2, 'Relic Handling', 'Archaeologist. Mark off 1 WP to study, activate or disarm an ancient device or relic you can touch, with Advantage on the roll. On a success with Balance, you also learn one of its hidden functions.', '', 'null'::jsonb, 'Yes', 1, '1', '1.2.0', 204),
  ('vanguard.academic.elementary', 'path', 'Vanguard', 'Vanguard', 'Academic', 2, 'Elementary', 'Detective. You have Advantage on Insight and Investigation rolls to spot lies, inconsistencies or forgeries. When you do, you may share your conclusion with an ally, giving them Advantage on their next roll against that person.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 205),
  ('vanguard.academic.hearty-meal', 'path', 'Vanguard', 'Vanguard', 'Academic', 3, 'Hearty Meal', 'Chef. During a Full Rest, you cook for the crew. Everyone who eats clears 1 additional WP and has Advantage on their next Resilience (RES) saving roll.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 206),
  ('vanguard.academic.universal-translator', 'path', 'Vanguard', 'Vanguard', 'Academic', 3, 'Universal Translator', 'Linguist. Once per Full Rest, you speak in a way that every listener understands, whatever their language, including droids and creatures that use language. For a Countdown (4), allies have Advantage on Influence rolls against those listeners.', '', 'null'::jsonb, 'No', 0, 'None', '1.2.0', 207),
  ('vanguard.academic.lost-knowledge', 'path', 'Vanguard', 'Vanguard', 'Academic', 3, 'Lost Knowledge', 'Archaeologist. Once per Full Rest, after studying a relic or archive, you may use one Tier 1 power from any path as if you knew it, using your Intelligence (INT) modifier for any casting roll. The knowledge fades at your next Full Rest.', '', 'null'::jsonb, 'Conditional', 0, 'None', '1.2.0', 208)
on conflict (id) do update set
  source_type = excluded.source_type, source_name = excluded.source_name, path = excluded.path, archetype = excluded.archetype,
  tier = excluded.tier, name = excluded.name, content = excluded.content, prerequisite_text = excluded.prerequisite_text,
  prerequisite = excluded.prerequisite, action_roll = excluded.action_roll, willpower_cost = excluded.willpower_cost,
  willpower_cost_note = excluded.willpower_cost_note, rules_version = excluded.rules_version, sort = excluded.sort;

-- Cards removed from the sheet since the last run
